// 标准帧(11bit ID)：直接写ID
BO_ 256 EngineData: 8 EMS                    // ID=0x100

// 扩展帧(29bit ID)：ID高位必须置1标记
BO_ 2147483904 ExtendedMsg: 8 BCM            // 2147483904 = 0x80000100
// 实际CAN ID = 0x100，但DBC中写成 0x80000100（最高位置1表示扩展帧）

// 更常见的写法：用负值表示扩展帧
BO_ -2147483392 ExtMsg2: 8 BCM               // 实际上是扩展帧 ID=0x200
